import { getComments } from "./api.js";
import useAbortableAsync from "./useAbortableAsync.js";

export default function useComments(slug) {
  const { value: comments, error, loading } = useAbortableAsync(
    (signal) => getComments(slug, { signal }),
    [slug],
    {
      initialValue: [],
      errorMessage: "Failed to load comments",
    },
  );

  return { comments, error, loading };
}

