"use strict";

function createCommentSeeder({ User, Article, Comment, demoData }) {
  async function seedDemoData() {
    const [user] = await User.findOrCreate({
      where: { username: demoData.seedUser.username },
      defaults: { username: demoData.seedUser.username },
    });

    const [article] = await Article.findOrCreate({
      where: { slug: demoData.articleSlug },
      defaults: { slug: demoData.articleSlug, userId: user.id },
    });

    const count = await Comment.count({ where: { articleId: article.id } });
    if (count === 0) {
      await Comment.bulkCreate(
        demoData.seedComments.map((body) => ({
          body,
          articleId: article.id,
          userId: user.id,
        })),
      );
    }
  }

  return {
    seedDemoData,
  };
}

module.exports = {
  createCommentSeeder,
};

